import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:pub_semver/pub_semver.dart';
import 'package:yaml/yaml.dart';
import 'package:yaml_edit/yaml_edit.dart';

import 'manifest_repository.dart';
import 'melos_overrides.dart';

/// The exact untracked override content owned by dep_sync, never user overrides.
const generatedResolutionOverride =
    '# Generated by dep-sync. Do not edit manually.\nresolution: workspace\n';

/// Prepares Pub workspace files without editing package pubspecs or SDK constraints.
///
/// Call [prepare] before checkout changes, then [PubWorkspacePlan.apply] after all
/// checkouts succeed. Existing user configuration must already be compatible;
/// only files recorded with their exact previous contents may be replaced.
class PubWorkspaceRepository {
  /// Creates a stateless workspace configuration adapter.
  const PubWorkspaceRepository();

  /// Includes the consumer, selected Git packages, local path dependencies, and
  /// explicit nested workspace members. [readFile] can read planned Git trees so
  /// validation uses the selected commits rather than stale local checkouts.
  Future<PubWorkspacePlan> prepare({
    required Directory workspace,
    required Directory consumer,
    required Iterable<Directory> packages,
    required Set<String> ignored,
    required Future<String?> Function(String path) readFile,
    required Future<bool> Function(String path) isTrackedFile,
  }) async {
    final root = workspace.path;
    final snapshots = <String, String?>{};
    String? local(String relative) {
      final file = _safeFile(root, relative);
      final content = file.existsSync() ? file.readAsStringSync() : null;
      snapshots[relative] = content;
      return content;
    }

    const statePath = '.dep-sync/pub-workspace-state.json';
    final stateSource = local(statePath);
    final previous = <String, String>{};
    final centralized = <String, Map<String, Object?>>{};
    if (stateSource != null) {
      final state = jsonDecode(stateSource);
      if (state is! Map || state['version'] != 1 || state['files'] is! Map) {
        throw StateError(
            'Invalid $statePath. Restore the workspace state file.');
      }
      final pins = state['centralized_overrides'];
      if (pins != null) {
        if (pins is! Map) {
          throw StateError('Invalid centralized override state.');
        }
        for (final entry in pins.entries) {
          final record = entry.value;
          if (entry.key is! String ||
              record is! Map ||
              !(record['value'] is String ||
                  (record['value'] is Map &&
                      (record['value'] as Map).length == 1 &&
                      (record['value'] as Map)['path'] is String)) ||
              record['origins'] is! Map) {
            throw StateError('Invalid centralized override state.');
          }
          _canonicalOverride(root, '.', record['value']);
          final origins = <String, String?>{};
          for (final origin in (record['origins'] as Map).entries) {
            if (origin.key is! String ||
                (origin.value != null && origin.value is! String)) {
              throw StateError('Invalid centralized override origin.');
            }
            _safeFile(root,
                p.posix.join(origin.key as String, 'pubspec_overrides.yaml'));
            origins[origin.key as String] = origin.value as String?;
          }
          centralized[entry.key as String] = {
            'value': record['value'],
            'origins': origins
          };
        }
      }
      for (final entry in (state['files'] as Map).entries) {
        final key = entry.key;
        final value = entry.value;
        if (key is! String ||
            value is! String ||
            !(key == 'pubspec.yaml' ||
                key.endsWith('/pubspec_overrides.yaml'))) {
          throw StateError('Invalid managed file in $statePath.');
        }
        _safeFile(root, key);
        previous[key] = value;
      }
    }
    final ignoredFiles = <String>{};
    for (final path in previous.keys
        .where((path) => path.endsWith('/pubspec_overrides.yaml'))) {
      final source =
          _safeFile(root, p.posix.join(p.posix.dirname(path), 'pubspec.yaml'));
      if (source.existsSync() &&
          ignored
              .contains(_map(source.readAsStringSync(), source.path)['name'])) {
        ignoredFiles.add(path);
      }
    }
    // Detect user edits before planning replacements or stale-file cleanup.
    for (final entry in previous.entries) {
      if (ignoredFiles.contains(entry.key)) continue;
      final content = local(entry.key);
      if (content != null && content != entry.value) {
        throw StateError(
            'Generated ${entry.key} was edited. Preserve your changes '
            'and resolve the conflict before generating a Pub workspace.');
      }
    }

    final members = <String, Map>{};
    final names = <String, String>{};
    final nestedChildren = <String>{};
    final nestedMembers = <String, List<String>>{};
    final queue = [consumer.path, ...packages.map((dir) => dir.path)];
    final generated = <String, String>{};
    final overrideMaps = <String, Map>{};
    final overrideSources = <String, String>{};
    final melosCandidates = <String, Map<String, String>>{};
    final migrations = <String, String>{};
    final melosEdits = <String, String>{};
    final removals = <String>{};
    var sdkConstraints = VersionConstraint.parse('>=3.6.0');
    while (queue.isNotEmpty) {
      final directory = p.normalize(queue.removeAt(0));
      final relative = p.relative(directory, from: root).replaceAll('\\', '/');
      _safeFile(root, p.posix.join(relative, 'pubspec.yaml'));
      if (members.containsKey(relative)) continue;
      final source = await readFile(p.join(directory, 'pubspec.yaml'));
      if (source == null) {
        throw StateError(
            'Missing pubspec.yaml for Pub workspace member $relative.');
      }
      final yaml = _map(source, '$relative/pubspec.yaml');
      final name = yaml['name'];
      if (name is! String || name.isEmpty) {
        throw StateError('Workspace member $relative needs a package name.');
      }
      if (ignored.contains(name)) {
        throw StateError('Ignored package $name is required as a local Pub '
            'workspace member. Remove the exclusion or change the local dependency.');
      }
      if (names.containsKey(name) && names[name] != relative) {
        throw StateError('Duplicate Pub workspace package $name in '
            '${names[name]} and $relative.');
      }
      names[name] = relative;
      sdkConstraints = sdkConstraints
          .intersect(_validateSdk(yaml, '$relative/pubspec.yaml'));
      if (sdkConstraints.isEmpty) {
        throw StateError(
            'Pub workspace members have incompatible Dart SDK constraints.');
      }
      members[relative] = yaml;
      // Pub rejects an intermediate pubspec that is not itself a workspace member.
      var ancestor = p.dirname(directory);
      while (p.isWithin(root, ancestor)) {
        final ancestorPubspec = p.join(ancestor, 'pubspec.yaml');
        if (await readFile(ancestorPubspec) != null) queue.add(ancestor);
        ancestor = p.dirname(ancestor);
      }

      final overridePath = p.posix.join(relative, 'pubspec_overrides.yaml');
      _safeFile(root, overridePath);
      final overrideSource = await readFile(p.join(root, overridePath));
      final overrides = overrideSource == null
          ? <dynamic, dynamic>{}
          : _map(overrideSource, overridePath);
      if (overrideSource != null) {
        overrideSources[relative] = overrideSource;
        final paths = melosManagedPathOverrides(overrideSource);
        if (paths != null && !await isTrackedFile(p.join(root, overridePath))) {
          melosCandidates[relative] = paths;
        }
      }
      final dependencyOverrides = overrides.containsKey('dependency_overrides')
          ? overrides['dependency_overrides']
          : yaml['dependency_overrides'];
      if (dependencyOverrides != null && dependencyOverrides is! Map) {
        throw StateError('dependency_overrides in $relative must be a map.');
      }
      overrideMaps[relative] = dependencyOverrides as Map? ?? {};
      final resolution = overrides.containsKey('resolution')
          ? overrides['resolution']
          : yaml['resolution'];
      if (relative != '.') {
        if (resolution != null && resolution != 'workspace') {
          throw StateError('Unsupported resolution in $relative.');
        }
        if (resolution != 'workspace') {
          if (overrideSource != null &&
              overrideSource != generatedResolutionOverride &&
              !melosCandidates.containsKey(relative)) {
            throw StateError(
                'Existing $overridePath needs resolution: workspace. '
                'Add it yourself; dep_sync will not overwrite user overrides.');
          }
          generated[overridePath] = generatedResolutionOverride;
        } else if (overrideSource == generatedResolutionOverride &&
            previous.containsKey(overridePath)) {
          // Keep an existing owned override only while it is still necessary.
          if (yaml['resolution'] != 'workspace') {
            generated[overridePath] = generatedResolutionOverride;
          }
        }
      } else if (resolution != null) {
        throw StateError(
            'The workspace root must not declare resolution: workspace.');
      }

      // Only dependency declarations introduce local members. An override must
      // not make its own target a member, which Pub would then forbid overriding.
      for (final section in ['dependencies', 'dev_dependencies']) {
        final declarations =
            overrides.containsKey(section) ? overrides[section] : yaml[section];
        if (declarations == null) continue;
        if (declarations is! Map) {
          throw StateError('$relative/$section must be a map.');
        }
        for (final entry in declarations.entries) {
          final value = entry.value;
          if (value is Map && value['path'] is String) {
            final path = value['path'] as String;
            if (p.isAbsolute(path) || p.windows.isAbsolute(path)) {
              throw StateError(
                  'Pub workspace path dependencies must be relative: $path.');
            }
            final target = p.normalize(p.join(directory, path));
            final memberSource = await readFile(_safeFile(
                    root,
                    p
                        .relative(p.join(target, 'pubspec.yaml'), from: root)
                        .replaceAll('\\', '/'))
                .path);
            if (memberSource == null ||
                _map(memberSource, target)['name'] != entry.key) {
              throw StateError(
                  'Missing or mismatched local package ${entry.key} at $target.');
            }
            queue.add(target);
          }
        }
      }
      final nested = overrides.containsKey('workspace')
          ? overrides['workspace']
          : yaml['workspace'];
      if (nested != null) {
        if (nested is! List || nested.any((item) => item is! String)) {
          throw StateError(
              'workspace in $relative must be a list of package paths.');
        }
        for (final path in nested.cast<String>()) {
          validateRelativePath(path);
          if (RegExp(r'[*?\[\]{}]').hasMatch(path)) {
            throw StateError(
                'Use explicit workspace member paths in $relative; '
                'workspace generation does not expand globs.');
          }
          final child = p.normalize(p.join(directory, path));
          final childRelative =
              p.relative(child, from: root).replaceAll('\\', '/');
          if (childRelative == relative ||
              nestedChildren.contains(childRelative)) {
            throw StateError(
                'Duplicate or cyclic nested workspace member $childRelative.');
          }
          nestedChildren.add(childRelative);
          nestedMembers.putIfAbsent(relative, () => []).add(childRelative);
          queue.add(child);
        }
      }
    }
    final rootSource = local('pubspec.yaml');
    final rootOverrideSource = local('pubspec_overrides.yaml');
    final rootOverrides = rootOverrideSource == null
        ? <dynamic, dynamic>{}
        : _map(rootOverrideSource, 'pubspec_overrides.yaml');
    final ownsRoot = rootSource == null || previous.containsKey('pubspec.yaml');
    final rootPins = <String, Object?>{};
    // Preserve override provenance across repeat pulls and changes of selected app.
    for (final entry in centralized.entries) {
      final origins = entry.value['origins'] as Map<String, String?>;
      for (final origin in origins.entries) {
        if (!members.containsKey(origin.key)) continue;
        final path = p.posix.join(origin.key, 'pubspec_overrides.yaml');
        if (local(path) != origin.value) {
          throw StateError('$path changed after centralizing ${entry.key}. '
              'Reconcile the override and its centralized override state before pulling.');
        }
        rootPins[entry.key] = entry.value['value'];
      }
    }
    final rootYaml = rootSource == null
        ? <dynamic, dynamic>{}
        : _map(rootSource, 'pubspec.yaml');
    final existingRootOverrides =
        rootOverrides.containsKey('dependency_overrides')
            ? rootOverrides['dependency_overrides']
            : ownsRoot
                ? rootPins
                : rootYaml['dependency_overrides'];
    if (existingRootOverrides != null && existingRootOverrides is! Map) {
      throw StateError('Root dependency_overrides must be a map.');
    }
    final pinLocations = <String, Map<String, Object?>>{};
    for (final owner in overrideMaps.entries) {
      for (final override in owner.value.entries) {
        if (!names.containsKey(override.key)) {
          pinLocations.putIfAbsent(
              override.key.toString(), () => {})[owner.key] = override.value;
        }
      }
    }
    if (!members.containsKey('.')) {
      for (final override in (existingRootOverrides as Map? ?? {}).entries) {
        pinLocations.putIfAbsent(override.key.toString(), () => {})['.'] =
            override.value;
      }
    }
    final pinRemovals = <String, Set<String>>{};
    for (final entry in pinLocations.entries) {
      final locations = entry.value;
      if (locations.length < 2) continue;
      final canonical = <String, Object?>{};
      for (final location in locations.entries) {
        final value = _canonicalOverride(root, location.key, location.value);
        if (value != null) canonical[location.key] = value;
      }
      if (canonical.length != locations.length) continue;
      if (canonical.values.map(jsonEncode).toSet().length != 1) {
        throw StateError('Conflicting overrides for ${entry.key}: '
            '${locations.entries.map((e) => '${e.key}: ${e.value}').join('; ')}. '
            'Choose a single override; no override files were changed.');
      }
      for (final owner in locations.keys.where((owner) => owner != '.')) {
        if (!melosCandidates.containsKey(owner) ||
            !(_map(overrideSources[owner]!, owner)['dependency_overrides']
                    as Map)
                .containsKey(entry.key)) {
          throw StateError(
              'Duplicate ${entry.key} override in protected configuration '
              '$owner. Consolidate it manually at the workspace root.');
        }
      }
      final value = canonical.values.first;
      if (value is Map) {
        final target = _safeFile(
            root, p.posix.join(value['path'] as String, 'pubspec.yaml'));
        final source = await readFile(target.path);
        if (source == null || _map(source, target.path)['name'] != entry.key) {
          throw StateError(
              'The shared path override for ${entry.key} does not point '
              'to a matching package. No override files were changed.');
        }
      }
      if (!ownsRoot &&
          jsonEncode(_canonicalOverride(root, '.',
                  (existingRootOverrides as Map? ?? {})[entry.key])) !=
              jsonEncode(value)) {
        throw StateError('Add ${entry.key}: $value to the existing user root '
            'dependency_overrides before consolidating duplicate Melos overrides.');
      }
      if (rootOverrides.containsKey('dependency_overrides') &&
          jsonEncode(_canonicalOverride(
                  root, '.', (existingRootOverrides as Map)[entry.key])) !=
              jsonEncode(value)) {
        throw StateError(
            'Root pubspec_overrides.yaml would hide the consolidated '
            '${entry.key} pin. Reconcile that root override manually.');
      }
      rootPins[entry.key] = value;
      final record = centralized.putIfAbsent(
          entry.key, () => {'value': value, 'origins': <String, String?>{}});
      if (jsonEncode(record['value']) != jsonEncode(value)) {
        throw StateError(
            'Conflicting recorded override for ${entry.key}. Reconcile its override state.');
      }
      final origins = record['origins'] as Map<String, String?>;
      for (final owner in locations.keys.where((owner) => owner != '.')) {
        pinRemovals.putIfAbsent(owner, () => {}).add(entry.key);
        origins[owner] = overrideSources[owner];
      }
    }
    if (rootOverrides.containsKey('dependency_overrides')) {
      for (final entry in rootPins.entries) {
        if (jsonEncode(_canonicalOverride(
                root, '.', (existingRootOverrides as Map)[entry.key])) !=
            jsonEncode(entry.value)) {
          throw StateError(
              'Root pubspec_overrides.yaml would hide the centralized '
              '${entry.key} override. Reconcile that root configuration manually.');
        }
      }
    }
    // Pub forbids overriding a workspace member, even with the same local path.
    // Only positively identified, untracked Melos artifacts can be migrated.
    for (final entry in melosCandidates.entries) {
      final relative = entry.key;
      final directory = p.join(root, relative);
      final redundant = entry.value.entries
          .where((override) =>
              names.containsKey(override.key) &&
              p.equals(p.normalize(p.join(directory, override.value)),
                  p.join(root, names[override.key]!)))
          .map((entry) => entry.key)
          .toList();
      redundant.addAll(pinRemovals[relative] ?? {});
      if (redundant.isEmpty) {
        // Preserve overrides for packages outside the selected workspace graph.
        if (members[relative]!['resolution'] != 'workspace' &&
            !(_map(overrideSources[relative]!, relative)['resolution'] ==
                'workspace')) {
          throw StateError('Existing $relative/pubspec_overrides.yaml needs '
              'resolution: workspace. Non-workspace overrides were not removed.');
        }
        generated.remove(p.posix.join(relative, 'pubspec_overrides.yaml'));
        continue;
      }
      final path = p.posix.join(relative, 'pubspec_overrides.yaml');
      migrations[path] = overrideSources[relative]!;
      final remaining = Map<Object?, Object?>.from(overrideMaps[relative]!);
      for (final name in redundant) {
        remaining.remove(name);
      }
      if (remaining.isNotEmpty) {
        // Remove only redundant paths. Keep version pins and non-member paths,
        // including their YAML formatting, in the existing Melos override file.
        final editor = YamlEditor(overrideSources[relative]!);
        for (final name in redundant) {
          editor.remove(['dependency_overrides', name]);
        }
        if (relative != '.' &&
            members[relative]!['resolution'] != 'workspace') {
          editor.update(['resolution'], 'workspace');
        }
        melosEdits[path] = editor.toString().replaceFirst(
            RegExp(r'^# melos_managed_dependency_overrides: .+$',
                multiLine: true),
            '# melos_managed_dependency_overrides: ${remaining.keys.join(',')}');
        generated.remove(path);
        overrideMaps[relative] = remaining;
        continue;
      }
      if (relative == '.' || members[relative]!['resolution'] == 'workspace') {
        generated.remove(path);
        removals.add(path);
      } else {
        generated[path] = generatedResolutionOverride;
      }
      // Dropping the file's override map reveals any original pubspec overrides.
      final original = members[relative]!['dependency_overrides'];
      if (original != null && original is! Map) {
        throw StateError('dependency_overrides in $relative must be a map.');
      }
      overrideMaps[relative] = original as Map? ?? {};
    }
    final overridesSeen = <String, String>{};
    void validateOverrides(String relative, Map overrides, String source) {
      for (final name in overrides.keys) {
        if (names.containsKey(name)) {
          throw StateError('Cannot override Pub workspace member "$name" in '
              '$source. Remove dependency_overrides.$name; workspace members '
              'already resolve to their local packages. Only untracked, fully '
              'Melos-managed files with matching path targets can be migrated automatically.');
        }
        final previousOwner = overridesSeen[name];
        if (previousOwner != null && previousOwner != relative) {
          throw StateError('Dependency "$name" is overridden in both '
              '$previousOwner and $relative. Keep a single override for the workspace.');
        }
        overridesSeen[name.toString()] = relative;
      }
    }

    for (final entry in overrideMaps.entries) {
      final file = overrideSources.containsKey(entry.key) &&
              !migrations.containsKey(
                  p.posix.join(entry.key, 'pubspec_overrides.yaml'))
          ? 'pubspec_overrides.yaml'
          : 'pubspec.yaml';
      validateOverrides(entry.key, entry.value, p.posix.join(entry.key, file));
    }
    // Nested members are listed by their parent and must not be listed twice.
    final paths = members.keys.where((path) => path != '.').toList()..sort();
    final rootMembers =
        paths.where((path) => !nestedChildren.contains(path)).toList();
    if (!members.containsKey('.')) {
      final rootYaml = rootSource == null
          ? <dynamic, dynamic>{}
          : _map(rootSource, 'pubspec.yaml');
      final overrides = rootOverrides.containsKey('dependency_overrides')
          ? rootOverrides['dependency_overrides']
          : ownsRoot
              ? rootPins
              : rootYaml['dependency_overrides'];
      if (overrides != null && overrides is! Map) {
        throw StateError('Root dependency_overrides must be a map.');
      }
      validateOverrides(
          '.',
          overrides as Map? ?? {},
          rootOverrides.containsKey('dependency_overrides')
              ? 'pubspec_overrides.yaml'
              : 'pubspec.yaml');
    }
    if (rootSource == null || previous.containsKey('pubspec.yaml')) {
      if (rootOverrides.containsKey('workspace') ||
          rootOverrides['resolution'] != null) {
        throw StateError(
            'Root pubspec_overrides.yaml conflicts with generated workspace settings. '
            'Manage the root pubspec yourself or remove the conflicting override.');
      }
      if (names.containsKey('dep_sync_workspace')) {
        throw StateError(
            'Package name dep_sync_workspace is reserved for the generated root.');
      }
      generated['pubspec.yaml'] =
          '# Generated by dep-sync. Do not edit manually.\n'
          'name: dep_sync_workspace\npublish_to: none\n'
          "environment:\n  sdk: '>=3.6.0'\n"
          'workspace: ${jsonEncode(rootMembers)}\n'
          '${rootPins.isEmpty ? '' : 'dependency_overrides: ${jsonEncode(rootPins)}\n'}';
    } else {
      final rootYaml = _map(rootSource, 'pubspec.yaml');
      sdkConstraints =
          sdkConstraints.intersect(_validateSdk(rootYaml, 'pubspec.yaml'));
      if (sdkConstraints.isEmpty) {
        throw StateError(
            'The root and members have incompatible Dart SDK constraints.');
      }
      if (rootYaml['resolution'] != null ||
          rootOverrides['resolution'] != null) {
        throw StateError(
            'The workspace root must not declare resolution: workspace.');
      }
      if (names.containsKey(rootYaml['name']) &&
          names[rootYaml['name']] != '.') {
        throw StateError(
            'The root has the same package name as a workspace member.');
      }
      final entries = rootOverrides.containsKey('workspace')
          ? rootOverrides['workspace']
          : rootYaml['workspace'];
      // All discovered nested members are in `members`, but only top-level
      // entries need to be explicitly present in an existing user's root list.
      if (entries is! List || entries.any((item) => item is! String)) {
        throw StateError(
            'Existing root pubspec.yaml needs an explicit workspace '
            'list. dep_sync will not overwrite it. Required members: ${paths.join(', ')}.');
      }
      final reachable = <String>{'.'};
      void visit(String relative) {
        if (!reachable.add(relative)) return;
        for (final child in nestedMembers[relative] ?? <String>[]) {
          visit(child);
        }
      }

      for (final path in entries.cast<String>()) {
        validateRelativePath(path);
        visit(p.posix.normalize(path));
      }
      final missing = paths.where((path) => !reachable.contains(path)).toList();
      if (missing.isNotEmpty) {
        throw StateError(
            'Add these members to the existing root workspace list: '
            '${missing.join(', ')}. User configuration was not overwritten.');
      }
    }
    final outputs = <String, String?>{};
    for (final entry in generated.entries) {
      final old = local(entry.key);
      if (old != null &&
          !previous.containsKey(entry.key) &&
          old != entry.value &&
          old != migrations[entry.key]) {
        throw StateError('Refusing to overwrite user file ${entry.key}.');
      }
      outputs[entry.key] = entry.value;
    }
    for (final entry in melosEdits.entries) {
      if (local(entry.key) != migrations[entry.key]) {
        throw StateError(
            '${entry.key} changed while preparing its Melos migration.');
      }
      outputs[entry.key] = entry.value;
    }
    for (final path in removals) {
      if (local(path) != migrations[path]) {
        throw StateError('$path changed while preparing its Melos migration.');
      }
      outputs[path] = null;
    }
    for (final path in previous.keys) {
      if (ignoredFiles.contains(path)) {
        // Keep ownership information without touching an excluded checkout.
        generated[path] = previous[path]!;
      } else if (!generated.containsKey(path)) {
        outputs[path] = null;
      }
    }
    for (final record in centralized.values) {
      final origins = record['origins'] as Map<String, String?>;
      for (final owner in origins.keys.toList()) {
        if (!members.containsKey(owner)) continue;
        final path = p.posix.join(owner, 'pubspec_overrides.yaml');
        origins[owner] =
            outputs.containsKey(path) ? outputs[path] : local(path);
      }
    }
    outputs[statePath] = '${const JsonEncoder.withIndent('  ').convert({
          'version': 1,
          'files': generated,
          if (centralized.isNotEmpty) 'centralized_overrides': centralized,
        })}\n';
    return PubWorkspacePlan._(root, snapshots, outputs, members.length);
  }
}

/// A validated batch of owned file edits, applied only after checkout succeeds.
class PubWorkspacePlan {
  PubWorkspacePlan._(
      this._root, this._snapshots, this._outputs, this.memberCount);
  final String _root;
  final Map<String, String?> _snapshots;
  final Map<String, String?> _outputs;

  /// Number of selected packages, including the consuming app.
  final int memberCount;

  /// Rechecks configuration snapshots and applies edits with rollback on failure.
  /// File replacement uses a sibling temporary file and rename.
  void apply() {
    for (final entry in _snapshots.entries) {
      final file = _safeFile(_root, entry.key);
      final current = file.existsSync() ? file.readAsStringSync() : null;
      // Fresh clones may remove generated member overrides; regeneration is safe.
      if (current != entry.value &&
          !(current == null && entry.value == generatedResolutionOverride)) {
        throw StateError(
            '${entry.key} changed during synchronization. Rerun pull.');
      }
    }
    final applied = <String>[];
    try {
      for (final entry in _outputs.entries) {
        _replace(_safeFile(_root, entry.key), entry.value);
        applied.add(entry.key);
      }
    } catch (_) {
      for (final path in applied.reversed) {
        _replace(_safeFile(_root, path), _snapshots[path]);
      }
      rethrow;
    }
  }
}

Map _map(String source, String label) {
  final yaml = loadYaml(source);
  if (yaml is! Map) throw StateError('$label must be a YAML map.');
  return yaml;
}

VersionConstraint _validateSdk(Map yaml, String label) {
  final environment = yaml['environment'];
  final constraint = environment is Map ? environment['sdk'] : null;
  if (constraint is String) {
    final parsed = VersionConstraint.parse(constraint);
    if (!parsed.isEmpty &&
        parsed.intersect(VersionRange(max: Version(3, 6, 0))).isEmpty) {
      return parsed;
    }
  }
  throw StateError(
      '$label must declare a Dart SDK lower bound of at least 3.6.0 '
      'for resolution: workspace. SDK constraints were not changed.');
}

File _safeFile(String root, String relative) {
  validateRelativePath(relative);
  var current = root;
  for (final part in p.posix.split(p.posix.normalize(relative))) {
    current = p.join(current, part);
    if (FileSystemEntity.typeSync(current, followLinks: false) ==
        FileSystemEntityType.link) {
      throw StateError(
          'Symlinks are not supported for Pub workspace files: $current.');
    }
  }
  return File(current);
}

void _replace(File file, String? content) {
  if (content == null) {
    if (file.existsSync()) file.deleteSync();
    return;
  }
  if (file.existsSync() && file.readAsStringSync() == content) return;
  file.parent.createSync(recursive: true);
  final temporary = file.parent.createTempSync('.dep-sync-workspace-');
  try {
    File(p.join(temporary.path, 'new')).writeAsStringSync(content);
    File(p.join(temporary.path, 'new')).renameSync(file.path);
  } finally {
    temporary.deleteSync(recursive: true);
  }
}

/// Converts local override paths to a safe root-relative form for comparison.
Object? _canonicalOverride(String root, String owner, Object? value) {
  if (value is String) return value;
  if (value is! Map || value.length != 1 || value['path'] is! String) {
    return null;
  }
  final path = value['path'] as String;
  if (p.isAbsolute(path) || p.windows.isAbsolute(path)) {
    throw StateError(
        'Consolidated path overrides must stay relative to the workspace.');
  }
  final target = p.normalize(p.join(root, owner, path));
  final relative = p.relative(target, from: root).replaceAll('\\', '/');
  _safeFile(root, p.posix.join(relative, 'pubspec.yaml'));
  return {'path': relative};
}
